    std::uint8_t control = 0;

    if (required > destinationCapacity) {
        *encodedBytes = destinationCapacity;
        if (destinationCapacity > 0) {
            std::int32_t index = 0;
            do {
                const std::uint8_t value = source[index];
                destination[index] = value;

