    const std::int32_t oldCursor = gCursor;
    while (static_cast<std::int32_t>(i) != oldCursor) {
        // 原记录表尾的下一槽起点是共享路径起点。
        const std::uint8_t* const source = i + 1 == kRecordCount
            ? reinterpret_cast<const std::uint8_t*>(gPath.data())
